CREATE TABLE notifications (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, recipient_user_id UUID REFERENCES users(id), role_code VARCHAR(40), event_type VARCHAR(60) NOT NULL, title VARCHAR(180) NOT NULL, message VARCHAR(1000) NOT NULL, severity VARCHAR(20) NOT NULL DEFAULT 'INFO', deep_link VARCHAR(240), due_at TIMESTAMP WITH TIME ZONE, escalated_at TIMESTAMP WITH TIME ZONE, read_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_notifications_recipient_read ON notifications(recipient_user_id,read_at,created_at);
CREATE INDEX idx_notifications_role_read ON notifications(role_code,read_at,created_at);
CREATE TABLE report_saved_views (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, owner_user_id UUID NOT NULL REFERENCES users(id), report_key VARCHAR(80) NOT NULL, view_name VARCHAR(120) NOT NULL, filters_json VARCHAR(4000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE report_export_audit (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, actor_id UUID REFERENCES users(id), report_key VARCHAR(80) NOT NULL, export_format VARCHAR(20) NOT NULL, row_count INT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE vendor_bills ADD COLUMN IF NOT EXISTS project_id UUID REFERENCES projects(id);
ALTER TABLE petty_cash_entries ADD COLUMN IF NOT EXISTS project_id UUID REFERENCES projects(id);
CREATE TABLE notification_preferences (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, in_app_enabled BOOLEAN NOT NULL DEFAULT TRUE, email_enabled BOOLEAN NOT NULL DEFAULT FALSE, reminder_enabled BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
